import { chromium } from "playwright";
const b = await chromium.launch();
const pg = await b.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
pg.on("pageerror", e => console.log("PAGEERR", e.message));
await pg.goto("https://kosmarafi.github.io/?t=" + Date.now(), { waitUntil: "load" });
await pg.waitForFunction(() => document.querySelector('[aria-label*="14 redes"]'), null, { timeout: 90000 });
await pg.waitForTimeout(6000);
await pg.evaluate(() => document.querySelectorAll("[id*=splash],.splash").forEach(e => e.remove()));
const d = await pg.$("#door");
await d.screenshot({ path: "a.png" }); await pg.waitForTimeout(2300); await d.screenshot({ path: "b.png" });
const pg2 = await b.newPage({ viewport: { width: 1280, height: 800 } });
await pg2.goto("https://kosmarafi.github.io/?t=" + Date.now(), { waitUntil: "load" }); await pg2.waitForTimeout(7000);
await pg2.evaluate(() => document.querySelectorAll("[id*=splash],.splash").forEach(e => e.remove()));
await (await pg2.$("#door")).screenshot({ path: "c.png" });
await b.close();
